INSERT INTO products (slug, kind, name, latin, number, category, methods, tagline, description, cook_time, weights, nutrition, best_with, badge, sort) VALUES
('spaghetti', 'spaghetti', 'Спагетти', 'Spaghetti', '№01', 'long', '["boil","fry"]'::jsonb, 'Классика, которая держит соус и не слипается.', 'Длинные, ровные и упругие. Из твёрдой пшеницы, прессуются через бронзовые матрицы — поверхность получается шероховатой, и соус буквально цепляется за каждую нить. Идеальны отварными, а на следующий день — обжаренными с яйцом.', 9, '[{"grams":400,"price":12900},{"grams":800,"price":23900}]'::jsonb, '{"kcal":344,"protein":12.5,"fat":1.4,"carbs":70.2}'::jsonb, '["Томатный соус","Сливочные соусы","Жарка с яйцом"]'::jsonb, 'Хит', 10),
('penne', 'penne', 'Перья', 'Penne Rigate', '№02', 'short', '["boil","fry","bake"]'::jsonb, 'Рифлёные трубочки, внутри которых прячется соус.', 'Косой срез, глубокие рифления и толстая стенка. Перья не разваливаются ни в кастрюле, ни на сковороде, ни в духовке под сыром. Универсальный солдат любой кухни.', 11, '[{"grams":400,"price":13500},{"grams":800,"price":24900}]'::jsonb, '{"kcal":344,"protein":12.5,"fat":1.4,"carbs":70.2}'::jsonb, '["Запеканки","Мясной соус","Жарка с овощами"]'::jsonb, 'Хит', 20),
('fusilli', 'fusilli', 'Спирали', 'Fusilli', '№03', 'shaped', '["boil","fry","bake"]'::jsonb, 'Три витка — три раза больше соуса.', 'Тугие спирали, которые закручивают в себя любой соус, сыр или обжаренный лук. Отлично держат форму в салатах и на сковороде — не превращаются в кашу даже на сильном огне.', 10, '[{"grams":400,"price":13500},{"grams":800,"price":24900}]'::jsonb, '{"kcal":344,"protein":12.5,"fat":1.4,"carbs":70.2}'::jsonb, '["Салаты","Песто","Сырные соусы"]'::jsonb, '', 30),
('farfalle', 'farfalle', 'Бантики', 'Farfalle', '№04', 'shaped', '["boil","bake"]'::jsonb, 'Любимые у детей. Тайно — у взрослых тоже.', 'Плотная серединка и тонкие гофрированные крылышки: одна порция — две текстуры. Бантики красиво смотрятся на тарелке и прекрасно работают в лёгких сливочных соусах.', 11, '[{"grams":400,"price":14500}]'::jsonb, '{"kcal":344,"protein":12.5,"fat":1.4,"carbs":70.2}'::jsonb, '["Сливки и курица","Горошек","Детское меню"]'::jsonb, 'Новинка', 40),
('conchiglie', 'conchiglie', 'Ракушки', 'Conchiglie', '№05', 'shaped', '["boil","bake"]'::jsonb, 'Каждая ракушка — маленькая чаша для соуса.', 'Глубокие ракушки с рифлёной спинкой. Внутри остаётся соус, фарш или расплавленный сыр — каждая ложка получается полной. Отличны для запекания.', 12, '[{"grams":400,"price":14500}]'::jsonb, '{"kcal":344,"protein":12.5,"fat":1.4,"carbs":70.2}'::jsonb, '["Фарш","Сыр","Запекание"]'::jsonb, '', 50),
('elbow', 'elbow', 'Рожки', 'Chifferi', '№06', 'short', '["boil","fry","bake"]'::jsonb, 'Вкус детства. Макароны по-флотски одобряют.', 'Те самые рожки. Быстро варятся, идеально жарятся с фаршем и луком и становятся основой для самой уютной запеканки. Одна пачка — ужин на всю семью.', 8, '[{"grams":400,"price":11900},{"grams":900,"price":22900}]'::jsonb, '{"kcal":344,"protein":12.5,"fat":1.4,"carbs":70.2}'::jsonb, '["По-флотски","Запеканка","С сыром"]'::jsonb, 'Хит', 60),
('rigatoni', 'rigatoni', 'Ригатони', 'Rigatoni', '№07', 'short', '["boil","bake"]'::jsonb, 'Большие трубки для больших аппетитов.', 'Крупные рифлёные трубки с толстой стенкой. Держат густые мясные соусы и выдерживают долгое запекание, оставаясь упругими.', 13, '[{"grams":400,"price":14900}]'::jsonb, '{"kcal":344,"protein":12.5,"fat":1.4,"carbs":70.2}'::jsonb, '["Болоньезе","Запекание","Густые соусы"]'::jsonb, '', 70),
('nest', 'nest', 'Гнёзда', 'Tagliatelle Nidi', '№08', 'long', '["boil","fry"]'::jsonb, 'Широкие ленты, свёрнутые в идеальную порцию.', 'Тальятелле, аккуратно уложенные в гнёзда. Одно гнездо — одна порция, никаких весов. Широкие ленты великолепны со сливочными соусами и грибами.', 7, '[{"grams":450,"price":17900}]'::jsonb, '{"kcal":344,"protein":12.5,"fat":1.4,"carbs":70.2}'::jsonb, '["Грибы","Сливки","Жарка"]'::jsonb, 'Премиум', 80),
('vermicelli', 'vermicelli', 'Вермишель', 'Capellini', '№09', 'soup', '["boil","fry"]'::jsonb, 'Паутинка для супа, который лечит всё.', 'Тонкая, быстрая, нежная. Готовится за 3 минуты прямо в бульоне. А если обжарить её до золотистого цвета перед варкой — получится совсем другой вкус.', 3, '[{"grams":400,"price":10900},{"grams":900,"price":19900}]'::jsonb, '{"kcal":344,"protein":12.5,"fat":1.4,"carbs":70.2}'::jsonb, '["Куриный суп","Молочный суп","Обжарка"]'::jsonb, '', 90),
('noodles', 'noodles', 'Лапша', 'Lapsha Domashnaya', '№10', 'long', '["boil","fry"]'::jsonb, 'Как у бабушки, только без муки на полу.', 'Широкая яичная лапша по домашнему рецепту. Для лагмана, куриного супа и жарки в воке — держит форму и впитывает вкус.', 6, '[{"grams":400,"price":15900}]'::jsonb, '{"kcal":356,"protein":13.2,"fat":2.3,"carbs":69.4}'::jsonb, '["Лагман","Суп","Вок"]'::jsonb, '', 100)
